import{_ as i,c as a,o as t,a2 as s}from"./chunks/framework.QTfwLiL8.js";const u=JSON.parse('{"title":"0010 Container Runtime Extensibility","description":"","frontmatter":{"github_repo":"https://github.com/gardener/enhancements","github_subdir":"geps/0010-container-runtime-extensibility","params":{"github_branch":"main"},"path_base_for_github_subdir":{"from":"content/docs/proposals/0010-container-runtime-extensibility/README.md","to":"README.md"},"title":"0010 Container Runtime Extensibility","prev":false,"next":false},"headers":[],"relativePath":"docs/proposals/0010-container-runtime-extensibility/index.md","filePath":"docs/proposals/0010-container-runtime-extensibility/index.md","lastUpdated":null}'),n={name:"docs/proposals/0010-container-runtime-extensibility/index.md"};function o(l,e,r,h,p,d){return t(),a("div",null,e[0]||(e[0]=[s(`<h1 id="gep-0010-gardener-extensibility-to-support-shoot-additional-container-runtimes" tabindex="-1">GEP-0010: Gardener Extensibility to Support Shoot Additional Container Runtimes <a class="header-anchor" href="#gep-0010-gardener-extensibility-to-support-shoot-additional-container-runtimes" aria-label="Permalink to &quot;GEP-0010: Gardener Extensibility to Support Shoot Additional Container Runtimes&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="/docs/proposals/0010-container-runtime-extensibility/readme/#gep-0010-gardener-extensibility-to-support-shoot-additional-container-runtimes">GEP-0010: Gardener Extensibility to Support Shoot Additional Container Runtimes</a><ul><li><a href="/docs/proposals/0010-container-runtime-extensibility/readme/#table-of-contents">Table of Contents</a></li><li><a href="/docs/proposals/0010-container-runtime-extensibility/readme/#summary">Summary</a></li><li><a href="/docs/proposals/0010-container-runtime-extensibility/readme/#motivation">Motivation</a><ul><li><a href="/docs/proposals/0010-container-runtime-extensibility/readme/#goals">Goals</a></li></ul></li><li><a href="/docs/proposals/0010-container-runtime-extensibility/readme/#proposal">Proposal</a></li><li><a href="/docs/proposals/0010-container-runtime-extensibility/readme/#design-details">Design Details</a></li></ul></li></ul><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Gardener-managed Kubernetes clusters are sometimes used to run sensitive workloads, which sometimes are comprised of OCI images originating from untrusted sources. Additional use-cases want to leverage economy-of-scale to run workloads for multiple tenants on the same cluster. In some cases, Gardener users want to use operating systems which do not easily support the Docker engine.</p><p>This proposal aims to allow Gardener shoot clusters to use CRI instead of the legacy Docker API, and to provide extension type for adding CRI shims (like <a href="https://gvisor.dev/" target="_blank" rel="noreferrer">GVisor</a> and <a href="https://katacontainers.io/" target="_blank" rel="noreferrer">Kata Containers</a>), which can be used to add support in Gardener shoot clusters for these runtimes.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to &quot;Motivation&quot;">​</a></h2><p>While pods and containers are intended to create isolated areas for concurrently running workloads on nodes, this isolation is not as robust as could be expected. Containers leverage the core Linux CGroup and Namespace features to isolate workloads, and many kernel vulnerabilities have the potential to allow processes to escape from their isolation. Once a process has escaped from its container, any other process running on the same node is compromised. Several projects try to mitigate this problem; for example Kata Containers allow isolating a Kubernetes Pod in a micro-vm, gVisor reduces the kernel attack surface by adding another level of indirection between the actual payload and the real kernel.</p><p>Kubernetes supports running pods using these alternate runtimes via the <a href="https://kubernetes.io/docs/concepts/containers/runtime-class/" target="_blank" rel="noreferrer">RuntimeClass</a> concept, which was promoted to Beta in Kubernetes 1.14. Once Kubernetes is configured to use the Container Runtime Interface to control pods, it becomes possible to leverage CRI and run specific pods using different Runtime Classes. Additionally, configuring Kubernetes to use CRI instead of the legacy Dockershim is <a href="https://events19.linuxfoundation.org/wp-content/uploads/2017/11/How-Container-Runtime-Matters-in-Kubernetes_-OSS-Kunal-Kushwaha.pdf" target="_blank" rel="noreferrer">faster</a>.</p><p>The motivation behind this proposal is to make all of this functionality accessible to shoot clusters managed by Gardener.</p><h3 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h3><ul><li>Gardener must allow configuration its managed clusters with the CRI interface instead of the legacy Dockershim.</li><li>Low-level runtimes like gVisor or Kata Containers are provided as Gardener extensions which are (optionally) installed into a landscape by the Gardener operator. There must be no runtime-specific knowledge in the core Gardener code.</li><li>It shall be possible to configure multiple low-level runtimes in shoot clusters, on the Worker Group level.</li></ul><h2 id="proposal" tabindex="-1">Proposal <a class="header-anchor" href="#proposal" aria-label="Permalink to &quot;Proposal&quot;">​</a></h2><p>Gardener today assumes that all supported operating systems have Docker pre-installed in the base image. Starting with Docker Engine 1.11, Docker itself was refactored and cleaned-up to be based on the <a href="https://containerd.io/" target="_blank" rel="noreferrer">containerd</a> library. The first phase would be to allow the change of the Kubelet configuration as described in the <a href="https://kubernetes.io/docs/setup/production-environment/container-runtimes/#containerd" target="_blank" rel="noreferrer">Container Runtimes</a> topic, so that Kubernetes would use containerd instead of the default Dockershim. This will be implemented for CoreOS, Ubuntu, and SuSE-CHost.</p><p>We will implement two Gardener extensions, providing gVisor and Kata Containers as options for Gardener landscapes. The <code>WorkerGroup</code> specification will be extended to allow specifying the CRI name and a list of additional required Runtimes for nodes in that group. For example:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">workers</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">- </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">worker-b8jg5</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  machineType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">m5.large</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  volumeType</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gp2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  volumeSize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">50Gi</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  autoScalerMin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  autoScalerMax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  maxSurge</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cri</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">containerd</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    containerRuntimes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gvisor</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kata-containers</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  machineImage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">coreos</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2135.6.0</span></span></code></pre></div><p>Each extension will need to address the following concerns:</p><ol><li>Add the low-level runtime binaries to the worker nodes. Each extension should get the runtime binaries from a container.</li><li>Hook the runtime binary into the containerd configuration file, so that the runtime becomes available to containerd.</li><li>Apply a label to each node that allows identifying nodes where the runtime is available.</li><li>Apply the relevant <code>RuntimeClass</code> to the shoot cluster, to expose the functionality to users.</li><li>Provide a separate binary with a <code>ValidatingWebhook</code> (deployable to the garden cluster) to catch invalid configurations. For example, Kata Containers on AWS requires a <code>machineType</code> of <code>i3.metal</code>, so any <code>Shoot</code> requests with a Kata Containers runtime and a different machine type on AWS should be rejected.</li></ol><h2 id="design-details" tabindex="-1">Design Details <a class="header-anchor" href="#design-details" aria-label="Permalink to &quot;Design Details&quot;">​</a></h2><ol><li><p>Change the nodes container runtime to work with CRI and ContainerD (Only if specified in the shoot spec):</p><ol><li><p>In order to configure each worker machine in the cluster to work with CRI, the following configurations should be done:</p><ul><li>Add kubelet execution flags: <ul><li><code>--container-runtime=remote</code></li><li><code>--container-runtime-endpoint=unix:///run/containerd/containerd.sock</code></li></ul></li><li>Make sure that default containerd configuration file exist in path <code>/etc/containerd/config.toml</code>.</li></ul></li><li><p>ContainerD and Docker configurations are different for each OS. To make sure the default configurations above work well in each worker machine, each OS extension would be responsible to configure them during the reconciliation of theOperatingSystemConfig:</p><ol><li>os-ubuntu: <ul><li>Create ContainerD unit Drop-In to execute ContainerD with the default configurations file in path <code>/etc/containerd/config.toml</code>.</li><li>Create the container runtime metadata file with a OS path for binaries installations: <code>/usr/bin</code>.</li></ul></li><li>os-coreos: <ul><li>Create ContainerD unit Drop-In to execute ContainerD with the default configurations file in path <code>/etc/containerd/config.toml</code>.</li><li>Create Docker Drop-In unit to execute Docker with the correct socket path of ContainerD.</li><li>Create the container runtime metadata file with a OS path for binaries installations: <code>/var/bin</code>.</li></ul></li><li>os-suse-chost: <ul><li>Create ContainerD service unit and execute ContainerD with the default configurations file in path <code>/etc/containerd/config.toml</code>.</li><li>Download and install ctr-cli which is not shipped with the current SuSe image.</li><li>Create the container runtime metadata file with a OS path for binaries installations <code>/usr/sbin</code>.</li></ul></li></ol></li><li><p>To rotate the ContainerD (CRI) logs we will activate the kubelet feature flag: <code>CRIContainerLogRotation=true</code>.</p></li><li><p>Docker monitor service will be replaced with equivalent ContainerD monitor service.</p></li></ol></li><li><p>Validate workers additional runtime configurations:</p><ol><li>Disallow additional runtimes with shoots &lt; 1.14</li><li>kata-container validation: Machine type support nested virtualization.</li></ol></li><li><p>Add support for each additional container runtime in the cluster.</p><ol><li><p>In order to install each additional available runtime in the cluster we should:</p><ol><li>Install the runtime binaries in each Worker&#39;s pool nodes that specified the runtime support.</li><li>Apply the relevant RuntimeClass to the cluster.</li></ol></li><li><p>The installation above should be done by a new kind of extension: ContainerRuntime resource. For each container runtime type (Kata-container/gvisor), a dedicate extension controller will be created.</p><ol><li><p>A label for each container runtime support will be added to every node that belongs to the worker pool. This should be done similarly to the way labels are created today for each node, through kubelet execution parameters (<code>_kubelet.flags: --node-labels</code>). When creating the OperatingSystemConfig (original) for the worker, each container runtime support should be mapped to a label on the node. For Example: label: <code>container.runtime.kata-containers=true</code> (<code>shoot.spec.cloud.&lt;IAAS&gt;.worker.containerRuntimes.kata-container</code>) label: <code>container.runtime.gvisor=true</code> (<code>shoot.spec.cloud.&lt;IAAS&gt;.worker.containerRuntimes.gvisor</code>)</p></li><li><p>During the shoot reconciliation (Similar steps to the Extensions today), Gardener will create new ContainerRuntime resource if a container runtime exist in at least one worker spec:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">extensions.gardener.cloud/v1alpha1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ContainerRuntime</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kata-containers-runtime-extension</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  namespace</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">shoot--foo--bar</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kata-containers</span></span></code></pre></div><p>Gardener will wait that all ContainerRuntimes extensions will be reconciled by the appropriate extensions controllers.</p></li><li><p>Each runtime extension controller will be responsible to reconcile its RuntimeContainer resource type. rc-kata-containers extension controller will reconcile RuntimeContainer resource from type kata-container and rc-gvisor will reconcile RuntimeContainer resource from gvisor. Reconciliation process by container runtime extension controllers:</p><ol><li>The runtime extension controller from specific type should apply a chart which responsible for the installation of the runtime container in the cluster: <ol><li>DaemonSet which will run a privileged pod on each node with the label: <code>container.runtime.&lt;type of the resource&gt;:true</code> The pod will be responsible for: <ul><li>Copy the runtime container binaries (From extension package ) to the relevant path in the host OS.</li><li>Add the relevant container runtime plugin section to the containerd configuration file (<code>/etc/containerd/config.toml</code>).</li><li>Restart containerd in the node.</li></ul></li><li>RuntimeClasses in the cluster to support the runtime class. For example:<div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node.k8s.io/v1beta1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">RuntimeClass</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gvisor</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">handler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">runsc</span></span></code></pre></div></li></ol></li><li>Update the status of the relevant RuntimeContainer resource to succeeded.</li></ol></li></ol></li></ol></li></ol>`,20)]))}const k=i(n,[["render",o]]);export{u as __pageData,k as default};
